🚀 Feature
Support metaprogramming for if self.training. Cos many many models have different training code vs inference code.
Example
class MyJITModule(torch.jit.ScriptModule):
    def __init__(self):
        super(MyJITModule, self).__init__()
        self.lnorm = nn.LayerNorm([10, 10, 10])

    @torch.jit.script_method
    def forward(self, x):
        if self.training:
            self.training_code_only(x)
        return x

    def training_code_only(self, x):
        # do some torchscript incompatible logic
        arr = [1,2,3]
        for i, k in enumerate(arr):
            x[k] += x[k]

        return self.lnorm(x)


